// nodename: Filter to Account Managers team
const ACCOUNT_MANAGERS_TEAM_ID = "163861030";

const reps = $input.all()
  .map(item => item.json)
  .filter(owner =>
    Array.isArray(owner.teams) &&
    owner.teams.some(team => team.id === ACCOUNT_MANAGERS_TEAM_ID)
  )
  .map(owner => ({
    ownerId:   owner.id,
    firstName: owner.firstName,
    lastName:  owner.lastName,
    email:     owner.email,
  }));

// One n8n item per rep so the rest of the workflow loops automatically
return reps.map(rep => ({ json: rep }));

// nodename: Bucket open deals (priority + stale)
const STALE_DAYS   = 60;
const PRIORITY_MAX = 5;
const STALE_MAX    = 10;
const DEAL_URL     = "https://app-eu1.hubspot.com/contacts/25187088/record/0-3/";

const now            = new Date();
const staleThreshold = new Date(now.getTime() - STALE_DAYS * 24 * 60 * 60 * 1000);

// Handle both shapes: one item with a results wrapper, OR n8n split into per-deal items
let rawDeals;
const firstJson = $input.first().json;
if (Array.isArray(firstJson.results)) {
  rawDeals = firstJson.results;
} else {
  rawDeals = $input.all().map(item => item.json);
}

function shapeDeal(deal) {
  const props = deal.properties || {};
  return {
    dealId:        deal.id,
    dealName:      props.dealname || "(unnamed deal)",
    amount:        props.amount ? Number(props.amount) : 0,
    closeDate:     props.closedate || null,
    lastContacted: props.notes_last_contacted || null,
    dealStage:     props.dealstage || null,
    link:          deal.url || (DEAL_URL + deal.id),
  };
}

const allDeals = rawDeals.map(shapeDeal);

// Priority calls: highest-value open deals (search already sorted by amount desc)
const priorityCalls = allDeals.slice(0, PRIORITY_MAX);

// Stale: close date already in the past OR not contacted in over 60 days
const staleDeals = allDeals
  .filter(deal => {
    const closeIsPast   = deal.closeDate     && new Date(deal.closeDate)     < now;
    const contactIsCold = deal.lastContacted && new Date(deal.lastContacted) < staleThreshold;
    return closeIsPast || contactIsCold;
  })
  .sort((a, b) => b.amount - a.amount)
  .slice(0, STALE_MAX);

return [{
  json: {
    priorityCalls,
    staleDeals,
  }
}];

// nodename: Shape uncontacted leads
const CONTACT_URL = "https://app-eu1.hubspot.com/contacts/25187088/record/0-1/";
const now = new Date();

let rawContacts;
const firstJson = $input.first().json;
if (Array.isArray(firstJson.results)) {
  rawContacts = firstJson.results;
} else {
  rawContacts = $input.all().map(item => item.json);
}

function daysSince(dateString) {
  if (!dateString) return null;
  const then = new Date(dateString);
  return Math.floor((now.getTime() - then.getTime()) / (24 * 60 * 60 * 1000));
}

function shapeContact(contact) {
  const props = contact.properties || {};
  const firstName = props.firstname || "";
  const lastName  = props.lastname || "";
  const fullName  = (firstName + " " + lastName).trim() || "(no name)";
  const assignedDate = props.hubspot_owner_assigneddate || props.createdate || null;

  return {
    contactId:         contact.id,
    name:              fullName,
    phone:             props.phone || props.mobilephone || null,
    assignmentAgeDays: daysSince(assignedDate),
    createdate:        props.createdate || null,
    link:              contact.url || (CONTACT_URL + contact.id),
  };
}

const uncontactedLeads = rawContacts.map(shapeContact);

return [{ json: { uncontactedLeads } }];

// nodename: Build Claude Payload
const MONTHLY_TARGET = 35000;

// --- Current rep (this loop iteration) ---
const rep = $('Loop Over Reps').item.json;

// --- Priority + stale deals (from the bucket node) ---
const deals         = $('Build Deal Buckets').item.json;
const priorityCalls = deals.priorityCalls || [];
const staleDeals    = deals.staleDeals    || [];

// --- Uncontacted leads (from the shaping node) ---
const uncontactedLeads = $('Shape Uncontacted Leads').item.json.uncontactedLeads || [];

// --- MTD closed-won: sum the raw search result (this node's direct input) ---
const mtd = $input.first().json;
let closedWonDeals = [];
let capHit = false;
if (Array.isArray(mtd.results)) {
  closedWonDeals = mtd.results;
  // Brief requires the figure to match HubSpot exactly - flag if more deals exist than we pulled
  if (typeof mtd.total === "number" && mtd.total > closedWonDeals.length) {
    capHit = true;
  }
}

let closedWonTotal = 0;
for (const deal of closedWonDeals) {
  const props = deal.properties || {};
  if (props.amount) {
    closedWonTotal = closedWonTotal + Number(props.amount);
  }
}

let percentOfTarget = 0;
if (MONTHLY_TARGET > 0) {
  percentOfTarget = Math.round((closedWonTotal / MONTHLY_TARGET) * 100);
}

// --- Days left in the month, London time ---
const nowLondon = DateTime.now().setZone("Europe/London");
const daysLeft  = Math.floor(nowLondon.endOf("month").diff(nowLondon, "days").days);

return [{
  json: {
    rep: {
      ownerId:$('Loop Over Reps').first().json.owner_id,   
      first_name:$('Loop Over Reps').first().json.first_name,
      email:$('Loop Over Reps').first().json.email ,
    },
    target: {
      closedWonTotal,
      monthlyTarget:  MONTHLY_TARGET,
      percentOfTarget,
      daysLeft,
      capHit,
    },
    priorityCalls,
    staleDeals,
    uncontactedLeads,
  }
}];
